<?php require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/calendar_view.php';$u=require_role('paciente');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$q=db()->prepare('UPDATE citas SET estado="cancelada" WHERE id=? AND paciente_id=(SELECT id FROM pacientes WHERE usuario_id=?) AND estado="programada" AND CONCAT(fecha," ",hora)>NOW()');$q->execute([$id,$u['id']]);flash('success',$q->rowCount()?'La cita fue cancelada.':'No se pudo cancelar esta cita.');go('paciente/mis_citas.php');}$citas=all('SELECT c.*,u.nombre,u.apellido_paterno,e.nombre especialidad,co.nombre consultorio,r.contenido receta FROM citas c JOIN medicos m ON m.id=c.medico_id JOIN usuarios u ON u.id=m.usuario_id LEFT JOIN especialidades e ON e.id=m.especialidad_id LEFT JOIN consultorios co ON co.id=c.consultorio_id LEFT JOIN recetas r ON r.cita_id=c.id WHERE c.paciente_id=(SELECT id FROM pacientes WHERE usuario_id=?) ORDER BY c.fecha DESC,c.hora DESC',[$u['id']]);header_ui('Mis citas');?><div class="page-intro"><h2>Tu historial de atención</h2><p>Consulta tus próximas citas, atenciones anteriores y recetas disponibles.</p></div><?php calendar_view('paciente'); ?><div class="panel"><div class="panel-heading"><h2>Historial de citas</h2><a class="btn btn-primary btn-sm" href="<?=url('paciente/agendar.php')?>">+ Nueva cita</a></div><?php if(!$citas):empty_state('Todavía no tienes citas','Comienza agendando tu primera consulta.','paciente/agendar.php','Agendar cita');else:?><div class="table-wrap"><table><thead><tr><th>Fecha / Hora</th><th>Especialista</th><th>Consultorio</th><th>Estado</th><th>Receta</th><th></th></tr></thead><tbody><?php foreach($citas as $c):?><tr><td><?=ui_date($c['fecha'])?><br><small><?=ui_time($c['hora'])?></small></td><td>Dr(a). <?=e($c['nombre'].' '.$c['apellido_paterno'])?><br><small><?=e($c['especialidad']??'—')?></small></td><td><?=e($c['consultorio']??'Por asignar')?></td><td><span class="badge <?= $c['estado']==='programada'?'badge-mint':'badge-muted'?>"><?=e(ucfirst($c['estado']))?></span></td><td><?=!empty($c['receta'])?'<details><summary>Ver receta</summary><p>'.nl2br(e($c['receta'])).'</p></details>':'—'?></td><td><?php if($c['estado']==='programada'&&$c['fecha'].' '.$c['hora']>date('Y-m-d H:i:s')):?><form method="post" onsubmit="return confirm('¿Cancelar esta cita?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="link-danger">Cancelar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php footer_ui();?>
